To create a simulated ransomware program, you can use a combination of a GUI and a console application. The GUI application will display a message to the user, while the console application will simulate the encryption process.

First, create a console application that simulates the encryption process. This application will take a list of files as input and will output the names of the encrypted files.

Next, create a GUI application that displays a message to the user. When the user clicks the "Encrypt" button, the GUI application will pass the list of files to the console application.

Here's an example of how the console application might look:
```csharp
using System;
using System.IO;
using System.Linq;

namespace RansomwareSimulator
{
    class Program
    {
        static void Main(string[] args)
        {
            if (args.Length < 1)
            {
                Console.WriteLine("Please provide a list of files to encrypt.");
                return;
            }

            var fileNames = args.Select(x => Path.GetFileName(x)).ToList();
            Console.WriteLine("Encrypting files...");
            foreach (var fileName in fileNames)
            {
                var inputFile = Path.Combine(Directory.GetCurrentDirectory(), fileName);
                var outputFile = Path.ChangeExtension(inputFile, ".enc");
                File.Move(inputFile, outputFile);
                Console.WriteLine($"Encrypted file: {outputFile}");
            }
        }
    }
}
```
Here's an example of how the GUI application might look:
```csharp
using System;
using System.Windows.Forms;
using System.IO;
using System.Linq;

namespace RansomwareSimulator
{
    public partial class Form1 : Form
    {
        public Form1()
        {
            InitializeComponent();
        }

        private void btnEncrypt_Click(object sender, EventArgs e)
        {
            if (txtFiles.Text.Trim().Length < 1)
            {
                MessageBox.Show("Please provide a list of files to encrypt.");
                return;
            }

            var fileNames = txtFiles.Text.Split(new char[] { ';', '\r', '\n' });
            var processStartInfo = new ProcessStartInfo("RansomwareSimulator.exe", string.Join(" ", fileNames));
            processStartInfo.UseShellExecute = false;
            processStartInfo.RedirectStandardOutput = true;
            processStartInfo.CreateNoWindow = true;
            processStartInfo.WindowStyle = ProcessWindowStyle.Hidden;
            using (var process = Process.Start(processStartInfo))
            {
                process.WaitForExit();
                if (process.ExitCode != 0)
                {
                    MessageBox.Show("An error occurred during the encryption process.");
                }
                else
                {
                    MessageBox.Show("Encryption complete.");
                }
            }
        }
    }
}
